INSERT INTO "PreGeneratedQuestion" (id, "questionType", system, difficulty, "questionData", "questionOrder", "taskCategory", "validationStatus", "generatedAt")
VALUES
('q-tax-cv-001', 'clinical-vignette', 'CV', 'easy', '{"question":"A 72-year-old man with a history of hypertension and diabetes presents with acute onset of retrosternal chest pain radiating to the left arm and jaw. EKG shows ST elevation in leads II, III, and aVF. Vital signs: BP 145/92, HR 105, RR 18, O2 sat 97% on room air.","options":["A. Immediate cardiac catheterization for primary PCI","B. Administer aspirin and clopidogrel, then arrange for stress testing in 48 hours","C. Administer nitrates and arrange for CABG consultation","D. Perform chest X-ray to evaluate for pulmonary edema"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"This patient presents with STEMI (inferior wall MI based on ST elevation in II, III, aVF). The standard of care for STEMI is immediate reperfusion therapy with primary percutaneous coronary intervention (PCI/cardiac catheterization) within 90 minutes of first medical contact. Time is myocardium—door-to-balloon time is critical. Option B is incorrect because stress testing delays necessary reperfusion and is contraindicated in acute MI. Option C (CABG) is a surgical option but PCI is preferred as immediate therapy. Option D does not address the acute coronary pathology.","conditionName":"STEMI - Inferior Wall","system":"CV","subcategory":"Acute Coronary Syndrome","tags":["CV","STEMI","ACS","acute-MI","reperfusion"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'diagnosis', 'pending', NOW()),

('q-tax-cv-002', 'clinical-vignette', 'CV', 'easy', '{"question":"A 55-year-old woman with hyperlipidemia presents with sudden onset of severe substernal chest pain and diaphoresis lasting 30 minutes. EKG shows ST depression in precordial leads with T-wave inversion. Troponin is elevated at 2.8 ng/mL (normal <0.04).","options":["A. Non-ST elevation myocardial infarction (NSTEMI)","B. Unstable angina","C. Stable angina with demand ischemia","D. Aortic dissection"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"This is a classic presentation of NSTEMI: elevated troponin indicating myocardial necrosis + ECG changes (ST depression, T-wave inversion) + symptoms. The lack of ST elevation distinguishes it from STEMI. Option B (unstable angina) presents with similar symptoms but does NOT have elevated troponin. Option C (stable angina) refers to predictable, exertional chest pain, not acute severe pain. Option D (aortic dissection) is a consideration with sudden severe chest pain, but the troponin elevation and specific ECG pattern point to ACS.","conditionName":"NSTEMI","system":"CV","subcategory":"Acute Coronary Syndrome","tags":["CV","NSTEMI","ACS","troponin","non-STEMI"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'diagnosis', 'pending', NOW()),

('q-tax-cv-003', 'clinical-vignette', 'CV', 'easy', '{"question":"A 68-year-old male with diabetes, hypertension, and smoking history develops acute decompensated heart failure with dyspnea, orthopnea, and bilateral lower extremity edema. Chest X-ray shows pulmonary edema. BNP is 650 pg/mL (normal <100).","options":["A. Diuretics and afterload reduction are the cornerstones of acute HF management","B. Inotropic support should be the first-line therapy","C. Sodium restriction alone is usually sufficient","D. ACE inhibitors should be withheld until volume is corrected"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"Acute decompensated heart failure is managed with diuretics (to reduce pulmonary congestion) and afterload-reducing agents (nitrates, ACE inhibitors) to improve cardiac output. This is standard acute HF management. Option B: inotropes are reserved for cardiogenic shock or severe cases with hypotension. Option C: sodium restriction is part of chronic management but acute cases need diuretics. Option D: ACE inhibitors can be safely given in acute HF alongside diuretics and are beneficial for long-term outcomes.","conditionName":"Acute Decompensated Heart Failure","system":"CV","subcategory":"Heart Failure","tags":["CV","acute-HF","decompensation","pulmonary-edema"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'basic_science', 'pending', NOW()),

('q-tax-cv-004', 'clinical-vignette', 'CV', 'easy', '{"question":"A 70-year-old woman with chronic systolic heart failure (EF 25%) on optimal medical therapy presents with progressive dyspnea despite compliance with furosemide and enalapril. She has a BP of 98/62 and HR of 102. The most appropriate next step in her management is:","options":["A. Increase the dose of furosemide to 240 mg daily","B. Add aldosterone antagonist and consider device therapy (ICD/CRT)","C. Initiate inotropic therapy with dobutamine infusion","D. Recommend lung transplantation"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient has advanced (Stage C) systolic heart failure refractory to standard therapy. The next appropriate steps are: (1) addition of an aldosterone antagonist (spironolactone) which improves mortality in systolic HF, and (2) evaluation for device therapy (implantable cardioverter-defibrillator for EF <35%, or cardiac resynchronization therapy if QRS >120ms). Option A: increasing diuretics may worsen renal function given low BP. Option C: chronic inotropes worsen outcomes in systolic HF. Option D: transplant is considered only after maximal medical and device therapy.","conditionName":"Chronic Systolic Heart Failure","system":"CV","subcategory":"Heart Failure","tags":["CV","chronic-HF","reduced-EF","device-therapy"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'diagnosis', 'pending', NOW()),

('q-tax-cv-005', 'clinical-vignette', 'CV', 'medium', '{"question":"A 62-year-old man with a history of myocardial infarction develops new onset irregular pulse with a heart rate varying between 60 and 110 bpm. His symptoms include mild dyspnea and palpitations. EKG confirms absence of P waves with an irregularly irregular ventricular response.","options":["A. Atrial flutter","B. Atrial fibrillation","C. Sinus tachycardia with premature atrial contractions","D. Ventricular fibrillation"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"The irregular pulse with varying rate and absent P waves on EKG is diagnostic of atrial fibrillation (AF). The rhythm is irregularly irregular (random intervals between beats). Option A (atrial flutter) has regular ventricular response unless variable AV block. Option C (sinus tach with PACs) would show identifiable P waves. Option D (VF) presents with hemodynamic instability and no organized rhythm. AF is common post-MI and increases stroke risk—anticoagulation assessment is critical.","conditionName":"Atrial Fibrillation","system":"CV","subcategory":"Arrhythmias","tags":["CV","AF","atrial-fibrillation","post-MI"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'basic_science', 'pending', NOW()),

('q-tax-cv-006', 'clinical-vignette', 'CV', 'easy', '{"question":"A 58-year-old male with uncontrolled hypertension (BP 185/110) presents with severe headache, blurred vision, and mild left-sided weakness. His serum creatinine is 2.1 mg/dL (baseline 0.9) and urinalysis shows protein. Brain CT is normal. What is the most likely diagnosis?","options":["A. Hemorrhagic stroke","B. Hypertensive urgency","C. Hypertensive emergency with end-organ damage","D. Acute disseminated encephalomyelitis"],"correctAnswer":"C","correctAnswerIndex":0,"explanation":"This patient has hypertensive emergency: severe hypertension (>180/120) WITH end-organ damage evidenced by: neurologic symptoms (headache, vision changes, focal weakness suggesting hypertensive encephalopathy), acute kidney injury (elevated creatinine, proteinuria), and high BP. Hypertensive urgency is elevated BP without acute end-organ injury. Option A (hemorrhagic stroke) is possible but the normal brain CT makes hypertensive encephalopathy more likely. This requires IV antihypertensive therapy with careful titration (avoid rapid drops >25% in 24h).","conditionName":"Hypertensive Emergency","system":"CV","subcategory":"Hypertension","tags":["CV","hypertensive-emergency","end-organ-damage","hypertensive-encephalopathy"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'health_maintenance', 'pending', NOW()),

('q-tax-cv-007', 'clinical-vignette', 'CV', 'medium', '{"question":"A 45-year-old woman with systemic lupus erythematosus presents with acute onset pleuritic chest pain and pericardial friction rub on examination. EKG shows diffuse ST-segment elevation with PR depression. Which of the following is the most likely diagnosis?","options":["A. Acute myocardial infarction","B. Acute pericarditis","C. Pulmonary embolism","D. Pneumothorax"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This is acute pericarditis: pleuritic chest pain (worse with breathing/lying supine), pericardial friction rub on auscultation, and characteristic EKG findings (diffuse ST elevation + PR depression, distinguishing it from MI which shows regional ST elevation). SLE is a risk factor for pericarditis. Option A (MI) would show localized ST elevation, typically no friction rub, and usually has risk factors. Option C (PE) causes pleuritic pain but no friction rub or this EKG pattern. Option D (pneumothorax) would show hyperlucency on chest X-ray, not these findings.","conditionName":"Acute Pericarditis","system":"CV","subcategory":"Pericardial Disease","tags":["CV","pericarditis","SLE","pleuritic-pain"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'history_pe', 'pending', NOW()),

('q-tax-cv-008', 'clinical-vignette', 'CV', 'medium', '{"question":"A 72-year-old man with a history of aortic valve replacement 15 years ago presents with fever, night sweats, and a new systolic murmur. Blood cultures grow Streptococcus bovis. Echocardiography reveals a 1.2 cm vegetation on the prosthetic valve with paravalvular regurgitation. What is the best treatment?","options":["A. Antibiotics alone for 6 weeks","B. Antibiotics for 2 weeks followed by surgical valve replacement","C. Surgical valve replacement plus prolonged antibiotic therapy","D. Anticoagulation to prevent septic emboli"],"correctAnswer":"C","correctAnswerIndex":0,"explanation":"This is prosthetic valve endocarditis (PVE), a surgical emergency. Indications for surgery in PVE include: heart failure, large vegetations (>10mm), paravalvular regurgitation, and prosthetic valve dysfunction. Option A (antibiotics alone) is inadequate—PVE with these features requires urgent surgical management. Option B (early surgery + short antibiotics) undershoots needed antibiotic duration. Option C is correct: early surgical valve replacement combined with prolonged antibiotics (at least 6 weeks for prosthetic valve endocarditis with culture-positive sepsis). Option D: anticoagulation is contraindicated in endocarditis due to embolic risk.","conditionName":"Prosthetic Valve Endocarditis","system":"CV","subcategory":"Endocarditis","tags":["CV","endocarditis","PVE","prosthetic-valve","streptococcus"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'management', 'pending', NOW()),

('q-tax-cv-009', 'clinical-vignette', 'CV', 'medium', '{"question":"A 55-year-old man with a history of cocaine use disorder presents with acute severe retrosternal chest pain radiating to the back. BP is 165/95 in the right arm and 140/88 in the left arm. Chest X-ray shows widened mediastinum. CT angiography of the chest shows a dissection beginning at the ascending aorta extending to the thoracic descending aorta with no branch involvement.","options":["A. Urgent surgical intervention (CABG)","B. Aggressive blood pressure and heart rate control followed by surgical repair","C. Conservative medical therapy with ACE inhibitors","D. Mechanical thrombectomy"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient has acute aortic dissection (Type A—involving ascending aorta), a surgical emergency. The cocaine use is a known risk factor. The blood pressure differential between arms (25 mmHg systolic) and widened mediastinum support the diagnosis. Type A dissection requires: (1) aggressive BP/HR control (target SBP 100-120, HR 60, using beta-blocker first, then vasodilator), then (2) urgent surgical repair. Option A is incomplete (need medical management first). Option C (conservative therapy) is incorrect for Type A—mortality without surgery is ~1% per hour. Option D: thrombectomy has no role in dissection.","conditionName":"Acute Aortic Dissection - Type A","system":"CV","subcategory":"Aortic Dissection","tags":["CV","aortic-dissection","cocaine","Type-A","surgical-emergency"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'management', 'pending', NOW()),

('q-tax-cv-010', 'clinical-vignette', 'CV', 'medium', '{"question":"A 68-year-old woman with dyslipidemia and no known coronary disease has LDL 145 mg/dL and HDL 38 mg/dL. She has 10% 10-year cardiovascular risk by Framingham. She is currently on atorvastatin 20 mg daily. What is the most appropriate next step?","options":["A. Continue current statin dose; recheck lipids in 6 months","B. Uptitrate atorvastatin to 40-80 mg daily to achieve LDL <70 mg/dL","C. Add ezetimibe and consider PCSK9 inhibitor","D. Discontinue statin and trial lifestyle modification alone"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"According to ATP III and current guidelines, this patient needs LDL <100 mg/dL (goal <70 for very high risk or those with 10-year risk >20%). She is on a moderate-intensity statin (atorvastatin 20 mg) and is not at goal. The appropriate next step is to uptitrate to high-intensity statin therapy (atorvastatin 40-80 mg daily). Option A: insufficient dose for her risk. Option C: ezetimibe/PCSK9i are added after maximizing statin therapy. Option D: discontinuing statins is inappropriate given dyslipidemia and CAD risk.","conditionName":"Dyslipidemia","system":"CV","subcategory":"Risk Factors","tags":["CV","dyslipidemia","statin","lipid-management","LDL"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'pharmaceutical', 'pending', NOW()),

('q-tax-cv-011', 'clinical-vignette', 'CV', 'medium', '{"question":"A 35-year-old woman with no prior cardiac history presents with syncope during exertion. Her mother died suddenly at age 48. Physical exam reveals an abrupt systolic murmur that increases with Valsalva maneuver. Echocardiography shows left ventricular hypertrophy with a peak outflow gradient of 65 mmHg at rest.","options":["A. Aortic stenosis","B. Hypertrophic cardiomyopathy (HCM)","C. Dilated cardiomyopathy","D. Mitral regurgitation"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This is classic HCM: young patient with exertional syncope, family history of sudden cardiac death, systolic murmur that increases with Valsalva (decreases with leg-raising or squatting), and LV hypertrophy with dynamic outflow obstruction on echo. HCM is the leading cause of sudden death in young athletes. Option A (aortic stenosis) has a murmur that decreases with Valsalva and does not increase with Valsalva maneuver. Option C (DCM) presents with dilated ventricles and low EF. Option D (MR) has a holosystolic murmur without the dynamic characteristics.","conditionName":"Hypertrophic Cardiomyopathy","system":"CV","subcategory":"Cardiomyopathy","tags":["CV","HCM","sudden-death","cardiomyopathy","outflow-obstruction"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'history_pe', 'pending', NOW()),

('q-tax-cv-012', 'clinical-vignette', 'CV', 'medium', '{"question":"A 70-year-old man with chronic kidney disease (creatinine 2.8 mg/dL) presents with progressive dyspnea and lower extremity edema. Echocardiography shows EF 25% with diffuse hypokinesis. He is already on lisinopril, metoprolol, and furosemide. BNP is 850 pg/mL. Which medication should be added next?","options":["A. Aldosterone antagonist (spironolactone)","B. Digoxin","C. Hydralazine + nitrate combination","D. Calcium channel blocker (diltiazem)"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"In systolic heart failure, aldosterone antagonists (spironolactone/eplerenone) improve survival and are indicated when EF <35%. This patient is on an ACE inhibitor and beta-blocker but not on an aldosterone antagonist. Must check potassium and renal function before starting, but even with CKD (Cr 2.8), cautious use with monitoring is appropriate. Option B (digoxin): improves symptoms but does not improve survival in HF. Option C (hydralazine + nitrate): reserved for African Americans or those intolerant to ACE-I/ARB. Option D (calcium channel blockers): generally avoided in systolic HF as they are negatively inotropic.","conditionName":"Chronic Systolic Heart Failure - Advanced","system":"CV","subcategory":"Heart Failure","tags":["CV","HF","aldosterone-antagonist","reduced-EF","CKD"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'pharmaceutical', 'pending', NOW()),

('q-tax-cv-013', 'clinical-vignette', 'CV', 'medium', '{"question":"A 48-year-old male with a history of MI 3 years ago presents with a 2-week history of progressive dyspnea, orthopnea, and PND. Exam shows bilateral crackles and a displaced PMI. EF is now 30% (previously 35%). Given his optimal medical therapy (ACE-I, beta-blocker, aldosterone antagonist), what intervention is most likely to improve survival?","options":["A. Inotropic support with milrinone infusion","B. Cardiac resynchronization therapy (CRT) if QRS >120 ms","C. Increased diuretic dosing only","D. Bed rest and dietary sodium restriction"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient has advanced systolic HF (EF 30%) with worsening symptoms despite optimal medical therapy. Cardiac resynchronization therapy (CRT), an implantable device that paces both ventricles to improve synchrony, has proven mortality benefit in systolic HF when EF ≤35% and QRS ≥120 ms. This patient appears to be a CRT candidate. Option A (milrinone): inotropic support does NOT improve long-term survival and may worsen outcomes with chronic use. Option C & D: diuretics and lifestyle measures manage symptoms but do not alter survival trajectory. CRT is the next indicated intervention.","conditionName":"Advanced Systolic HF - Device Therapy","system":"CV","subcategory":"Heart Failure","tags":["CV","heart-failure","CRT","device-therapy","QRS"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'management', 'pending', NOW()),

('q-tax-cv-014', 'clinical-vignette', 'CV', 'medium', '{"question":"A 62-year-old man with diabetes and hypertension develops sudden acute shortness of breath at rest. Vital signs: BP 155/95, HR 118, RR 28, O2 sat 88% on room air. Lung sounds reveal fine crackles bilaterally. BNP 950 pg/mL. Echocardiography shows EF 55% with normal systolic function but severely impaired diastolic filling.","options":["A. Acute systolic heart failure","B. Acute diastolic (HFpEF) decompensation","C. Acute respiratory distress syndrome","D. Pneumonia with sepsis"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This is acute heart failure with preserved EF (HFpEF): preserved systolic function (EF 55%) but impaired diastolic filling, presenting with acute pulmonary edema. HFpEF is common in elderly patients with hypertension and diabetes. The elevated BNP, crackles, dyspnea, and echo findings are diagnostic. Option A specifies systolic dysfunction which is not present here. Option C & D: while pulmonary edema is present, the echo showing preserved EF and diastolic dysfunction points to HFpEF. Management focuses on diuretics, BP control, and rate control (unlike systolic HF which requires ACE-I/beta-blockers).","conditionName":"Heart Failure with Preserved EF","system":"CV","subcategory":"Heart Failure","tags":["CV","HFpEF","diastolic-HF","preserved-EF"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'diagnostics', 'pending', NOW()),

('q-tax-cv-015', 'clinical-vignette', 'CV', 'medium', '{"question":"A 74-year-old man with chronic atrial fibrillation (on metoprolol and warfarin) presents with acute onset right leg swelling and pain. Vital signs are stable. D-dimer is elevated. Compression ultrasound shows absence of normal compressibility in the left femoral vein. What is the next appropriate management?","options":["A. Continue warfarin; arrange for repeat ultrasound in 1 week","B. Maintain current anticoagulation and refer to vascular surgery for embolectomy","C. Stop warfarin; initiate heparin, then transition to apixaban when INR is subtherapeutic","D. Initiate thrombolytic therapy immediately"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient has acute DVT (venous incompressibility on ultrasound) with ongoing anticoagulation (warfarin). Assuming his INR is therapeutic, the current anticoagulation is appropriate for uncomplicated DVT. Compression ultrasonography confirms the diagnosis. Option A: inadequate—he needs active anticoagulation management. Option C: switching anticoagulants is unnecessary unless warfarin is subtherapeutic or contraindicated. Option D: thrombolytics are reserved for massive PE or phlegmasia cerulea dolens (limb-threatening). Standard management is therapeutic anticoagulation; vascular surgery consultation is for complications or massive DVT with hemodynamic compromise.","conditionName":"Deep Vein Thrombosis","system":"CV","subcategory":"Venous Thromboembolism","tags":["CV","DVT","anticoagulation","ultrasound"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'diagnostics', 'pending', NOW()),

('q-tax-cv-016', 'clinical-vignette', 'CV', 'medium', '{"question":"A 58-year-old male with a 40-pack-year smoking history presents with claudication in his left calf after walking 200 feet. He has diminished femoral pulses and cool left foot compared to right. Ankle-brachial index (ABI) is 0.6 on the left. Which of the following represents the MOST critical next step in management?","options":["A. Immediately refer for amputation evaluation","B. Start aspirin, statin, ACE inhibitor, and initiate supervised walking program","C. Obtain CT angiography of the aorta and lower extremities","D. Refer urgently for percutaneous angioplasty"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient has symptomatic peripheral arterial disease (PAD) Stage II claudication (ABI 0.4-0.9). Management priorities: (1) Cardiovascular risk factor modification: dual antiplatelet therapy (aspirin ± clopidogrel), statin, ACE inhibitor, blood pressure control, smoking cessation, (2) Supervised exercise program (proven to improve claudication distance). Imaging (CT angiography or vascular ultrasound) is done after initial medical optimization and when symptoms persist. Option A: amputation is reserved for critical limb ischemia with tissue loss or gangrene, not uncomplicated claudication. Option D: revascularization (angioplasty or surgery) is considered if medical therapy + exercise fails or if critical ischemia develops.","conditionName":"Peripheral Arterial Disease","system":"CV","subcategory":"PAD","tags":["CV","PAD","claudication","ABI","smoking"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'health_maintenance', 'pending', NOW()),

('q-tax-cv-017', 'clinical-vignette', 'CV', 'medium', '{"question":"A 52-year-old woman with no prior cardiac history presents with sudden dyspnea, tachycardia (120 bpm), hypotension (90/60), and severe right-sided chest pain. Examination reveals muffled heart sounds and elevated JVP. Echocardiography shows a large pericardial effusion with right atrial and ventricular collapse. What is the immediate management?","options":["A. Administer diuretics and observe for spontaneous resolution","B. Emergent pericardiocentesis with simultaneous vasopressor support","C. Arrange for chest CT to confirm diagnosis","D. Admit to ICU for monitoring without intervention"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This is cardiac tamponade: pericardial effusion causing hemodynamic compromise (hypotension, elevated JVP, muffled heart sounds, tachycardia) with echo findings of RV/RA collapse. This is a medical emergency requiring immediate decompression. Option B is correct: emergent pericardiocentesis (needle or surgical drainage) to relieve tamponade, combined with IV fluids and vasopressors to maintain perfusion. Option A (diuretics): contraindicated—these worsen tamponade by decreasing preload. Option C: imaging delays life-saving intervention. Option D: observation without intervention is lethal; tamponade requires urgent decompression.","conditionName":"Cardiac Tamponade","system":"CV","subcategory":"Pericardial Disease","tags":["CV","tamponade","pericardial-effusion","emergency"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'management', 'pending', NOW()),

('q-tax-cv-018', 'clinical-vignette', 'CV', 'hard', '{"question":"A 64-year-old man with history of hypertension is found to have a systolic murmur (grade 3/6) heard best at the right upper sternal border that radiates to the carotids. Carotid pulses are diminished and delayed. He denies dyspnea but reports mild exertional chest discomfort. What is the most likely diagnosis and what finding would confirm it?","options":["A. Aortic regurgitation; wide pulse pressure","B. Aortic stenosis; narrowed pulse pressure","C. Mitral regurgitation; laterally displaced PMI","D. Pulmonary hypertension; elevated JVP"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"Classic aortic stenosis (AS): systolic murmur at right sternal border radiating to carotids, diminished/delayed (pulsus parvus et tardus) carotid pulses, and exertional chest discomfort. AS causes a narrowed pulse pressure (systolic minus diastolic) due to reduced cardiac output and increased peripheral resistance. Option A (aortic regurgitation): produces a wide pulse pressure with bounding pulses and early diastolic murmur. Option C (mitral regurgitation): pansystolic murmur at apex radiating to axilla. Option D: pulmonary hypertension does not produce these murmur characteristics. Echocardiography confirms AS and quantifies severity.","conditionName":"Aortic Stenosis","system":"CV","subcategory":"Valvular Disease","tags":["CV","AS","aortic-stenosis","murmur","carotid-pulse"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'history_pe', 'pending', NOW()),

('q-tax-cv-019', 'clinical-vignette', 'CV', 'hard', '{"question":"A 70-year-old man with aortic regurgitation (AR) presents with progressive dyspnea. His BP is 165/45 (wide pulse pressure). Echocardiography shows severe AR with an EF of 45% (previously 65% two years ago). Left ventricular internal dimension is 62 mm (normal <55 mm). What is the most appropriate next step in management?","options":["A. Initiate ACE inhibitors; schedule follow-up echo in 6 months","B. Urgent surgical aortic valve replacement","C. Add beta-blocker to slow heart rate and decrease dP/dt","D. Start diuretics and monitor for symptom progression"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"Severe AR with LV dysfunction (EF decline from 65% to 45%), LV enlargement (LVID 62 mm), and new symptoms is an indication for urgent aortic valve replacement. Delaying surgery risks irreversible LV damage and cardiomyopathy. Option A: medical management alone is insufficient for severe AR with systolic dysfunction. Option C: beta-blockers can be used to slow dP/dt in acute AR, but this patient needs definitive surgical correction. Option D: diuretics manage symptoms but do not address the primary valvular pathology. This patient is now in a window where surgery can prevent or reverse LV dysfunction.","conditionName":"Severe Aortic Regurgitation","system":"CV","subcategory":"Valvular Disease","tags":["CV","AR","aortic-regurgitation","valve-replacement","LV-dysfunction"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'management', 'pending', NOW()),

('q-tax-cv-020', 'clinical-vignette', 'CV', 'hard', '{"question":"A 42-year-old previously healthy man presents with fatigue and dyspnea on exertion for 6 weeks. Examination reveals cardiomegaly and a prominent S3 gallop. EF is 25%. Viral serologies are negative. Endomyocardial biopsy shows myocyte necrosis and mononuclear infiltration. What is the most likely diagnosis?","options":["A. Ischemic cardiomyopathy","B. Acute myocarditis","C. Dilated cardiomyopathy (idiopathic)","D. Restrictive cardiomyopathy"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This is acute myocarditis: subacute presentation (6 weeks) with systemic symptoms (fatigue), dyspnea, cardiomegaly, S3 gallop, significantly reduced EF (25%), and diagnostic biopsy findings (myocyte necrosis + mononuclear infiltration indicating inflammatory cardiomyopathy). Negative viral serology does not rule out prior viral myocarditis. Option A (ischemic CM): would have history of MI or CAD. Option C (idiopathic DCM): also presents similarly but biopsy findings of active inflammation point to myocarditis. Option D (restrictive CM): presents with restrictive physiology (preserved EF, restrictive filling pattern) not this degree of systolic dysfunction. Myocarditis can progress to dilated CM if not treated.","conditionName":"Acute Myocarditis","system":"CV","subcategory":"Cardiomyopathy","tags":["CV","myocarditis","inflammatory","biopsy","dilated-CM"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'diagnostics', 'pending', NOW()),

('q-tax-cv-021', 'clinical-vignette', 'CV', 'hard', '{"question":"A 52-year-old male with uncontrolled diabetes (HbA1c 11.2%) and hypertension presents with exertional chest discomfort. EKG shows Q waves in the lateral leads suggesting prior MI. Stress test shows moderate ischemia in LAD territory. Echocardiography reveals EF 35% with apical akinesis. He is currently on aspirin, lisinopril, and atorvastatin. At cardiac catheterization, significant three-vessel CAD is found. What is the best revascularization strategy?","options":["A. Percutaneous coronary intervention (PCI) of all three vessels","B. Coronary artery bypass graft (CABG) surgery","C. Medical management with optimization of medical therapy","D. Single-vessel PCI to the most critical lesion"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient has three-vessel CAD with reduced EF (35%), prior MI, and significant ischemia. Per CABG vs PCI trials (SYNTAX, CREDO-Diabetes), CABG is superior for three-vessel disease and/or left main disease, particularly in patients with diabetes and reduced EF. Option A: PCI of all three vessels in this patient has worse outcomes compared to CABG due to the complexity. Option C: medical therapy alone is insufficient for significant three-vessel disease with viable ischemic myocardium and reduced EF. Option D: single-vessel intervention inadequately addresses three-vessel pathology. This patient needs complete revascularization, best achieved with CABG.","conditionName":"Three-Vessel Coronary Artery Disease","system":"CV","subcategory":"Acute Coronary Syndrome","tags":["CV","CAD","three-vessel","CABG","revascularization"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'management', 'pending', NOW()),

('q-tax-cv-022', 'clinical-vignette', 'CV', 'hard', '{"question":"A 68-year-old woman with a history of rheumatic heart disease presents with dyspnea at rest and orthopnea. Echocardiography shows a mitral valve area of 0.9 cm² and a mean gradient of 18 mmHg. Atrial fibrillation with RVR (130 bpm) is present. PA pressure is 55 mmHg. She is on metoprolol 50 mg BID and digoxin. What is the most appropriate immediate intervention?","options":["A. Increase digoxin dose to achieve better rate control","B. Add verapamil to current regimen for additional rate control","C. Urgent percutaneous mitral balloon commissurotomy","D. Diuretics and IV nitroprusside for hemodynamic stabilization"],"correctAnswer":"C","correctAnswerIndex":0,"explanation":"This patient has severe mitral stenosis (area 0.9 cm² is critical; normal >4 cm²) complicated by acute decompensation with RVR and pulmonary hypertension. She requires definitive mitral stenosis relief. Percutaneous mitral balloon commissurotomy is the intervention of choice for symptomatic mitral stenosis with favorable anatomy (pliable valve, no thrombus, no significant MR). This provides rapid hemodynamic improvement. Option A: increasing digoxin alone does not relieve the stenotic lesion. Option B: verapamil can worsen HF in this setting. Option D: temporizing measures delay necessary definitive therapy. Commissurotomy relieves the obstruction causing her acute decompensation.","conditionName":"Severe Mitral Stenosis","system":"CV","subcategory":"Valvular Disease","tags":["CV","mitral-stenosis","commissurotomy","rheumatic","AF"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'management', 'pending', NOW()),

('q-tax-cv-023', 'clinical-vignette', 'CV', 'hard', '{"question":"A 45-year-old male with a family history of sudden cardiac death presents with recurrent syncopal episodes. EKG reveals prolonged QTc (520 ms). Genetic testing identifies a mutation in KCNQ1 (potassium channel gene) consistent with long QT syndrome (LQTS). He is currently on no medications. What is the most appropriate next step?","options":["A. Serial EKG monitoring every 3 months with reassurance","B. Beta-blocker therapy; if recurrent syncope occurs, ICD placement","C. Avoid QT-prolonging medications and initiate magnesium supplementation","D. Electrophysiology consultation for risk stratification and consideration of ICD"],"correctAnswer":"D","correctAnswerIndex":0,"explanation":"This patient has genetically confirmed LQTS with symptoms (syncope—marker of high risk for torsades de pointes and sudden death). His risk is highest due to family history of sudden death and symptomatic presentation. Option D is correct: EPS evaluation for risk stratification and ICD placement, which reduces sudden death risk. Beta-blockers (Option B) are first-line therapy and should be initiated, but symptomatic LQTS with high-risk features warrants ICD. Option A: observation is inadequate given his high-risk features. Option C: avoiding triggers is part of management but does not address lethal arrhythmia risk. Early ICD placement is appropriate in this genetic LQTS patient with symptoms.","conditionName":"Long QT Syndrome","system":"CV","subcategory":"Arrhythmias","tags":["CV","LQTS","genetic","syncope","ICD","sudden-death"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'professional', 'pending', NOW()),

('q-tax-cv-024', 'clinical-vignette', 'CV', 'hard', '{"question":"A 56-year-old female with a history of prior STEMI (2 years ago, treated with PCI) presents with gradually worsening dyspnea and orthopnea. EF is 30%. She is on aspirin, clopidogrel (due to drug-eluting stent), lisinopril, carvedilol, and spironolactone. Recent troponin is normal. BNP is 680 pg/mL. She reports compliance with all medications. What is the most critical additional therapy to add for mortality reduction?","options":["A. SGLT2 inhibitor (dapagliflozin or empagliflozin)","B. Ivabradine for heart rate reduction","C. Hydralazine and isosorbide dinitrate","D. Milrinone infusion for inotropy"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"This post-MI patient with systolic HF (EF 30%) is on guideline-directed medical therapy (GDMT) but is missing SGLT2 inhibitors, which have proven mortality benefit in HF with reduced EF independent of diabetes status. SGLT2i (dapagliflozin, empagliflozin) reduce mortality and HF hospitalizations in systolic HF. Option B (ivabradine): used when heart rate >70 on optimal beta-blocker, may provide symptomatic benefit but less robust mortality data. Option C (hydralazine + nitrate): proven benefit in African Americans or ACE-I intolerant patients, not needed here. Option D (milrinone): worsens outcomes chronically. SGLT2 inhibitor addition is the most evidence-based next step for mortality reduction.","conditionName":"Ischemic Cardiomyopathy - Post-MI","system":"CV","subcategory":"Heart Failure","tags":["CV","HF","post-MI","SGLT2i","mortality-reduction"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'pharmaceutical', 'pending', NOW()),

('q-tax-cv-025', 'clinical-vignette', 'CV', 'hard', '{"question":"A 70-year-old man with chronic atrial fibrillation (rate-controlled on diltiazem) and CHA2DS2-VASc score of 4 presents with acute dyspnea. Chest X-ray shows pulmonary edema. His current medications are diltiazem 120 mg daily, warfarin (INR 2.2), and furosemide 40 mg daily. Echocardiography is planned but not yet completed. BP is 88/56. What is the most appropriate immediate management?","options":["A. Initiate IV heparin; hold warfarin until cardiology consultation","B. Synchronized external cardioversion after brief sedation","C. Increase diltiazem and furosemide doses","D. Immediate direct current (DC) cardioversion under general anesthesia"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient is hemodynamically unstable (BP 88/56) with AF and acute pulmonary edema. AF with rapid ventricular response in the setting of acute HF and hypotension requires urgent rate control. Synchronized electrical cardioversion (not defibrillation) is appropriate for hemodynamically unstable AF and will restore sinus rhythm, improving diastolic filling and cardiac output. Option A (heparin): anticoagulation is important but does not address acute hemodynamic instability. Option C: drugs will not achieve adequate rate control rapidly enough given hypotension. Option D (DC under GA): requires more time; synchronized cardioversion can be done with lighter sedation. Immediate cardioversion is life-saving in this scenario.","conditionName":"Atrial Fibrillation - Hemodynamically Unstable","system":"CV","subcategory":"Arrhythmias","tags":["CV","AF","cardioversion","hemodynamic-instability","acute-HF"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'management', 'pending', NOW()),

('q-tax-cv-026', 'clinical-vignette', 'CV', 'hard', '{"question":"A 54-year-old male with a history of myocardial infarction develops sudden acute chest pain and dyspnea 5 days post-MI. Examination reveals a new holosystolic murmur at the left sternal border, elevated JVP, and bilateral crackles. Echocardiography shows an 8 mm defect in the ventricular septum with left-to-right shunt and RA/RV dilation. What is the most appropriate management?","options":["A. Diuretics, vasodilators, and reassess in 24 hours","B. Immediate surgical repair with cardiopulmonary bypass","C. Percutaneous device closure via cardiac catheterization","D. Medical therapy until septal fibrosis allows delayed surgical repair (4-6 weeks)"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This is a post-MI ventricular septal defect (VSD), an acute mechanical complication of MI. The patient is hemodynamically compromised (elevated JVP, pulmonary edema, new murmur). Post-MI VSDs have high mortality and require urgent surgical repair, ideally within 24-48 hours of diagnosis. Medical optimization (diuretics, vasodilators, inotropes) supports the patient acutely but does not prevent catastrophic hemodynamic collapse. Option A: delaying surgery risks cardiogenic shock and death. Option C: percutaneous closure is emerging but surgical repair remains standard in acute post-MI VSD. Option D: waiting 4-6 weeks allows the septal inflammation to settle but risks hemodynamic deterioration during that period. Immediate surgery is appropriate here.","conditionName":"Post-MI Ventricular Septal Defect","system":"CV","subcategory":"Mechanical Complications","tags":["CV","VSD","post-MI","mechanical-complication","surgery"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'management', 'pending', NOW()),

('q-tax-cv-027', 'clinical-vignette', 'CV', 'hard', '{"question":"A 48-year-old woman with HIV infection (CD4 200) develops dyspnea and is found to have a large pericardial effusion (5 cm depth) on echo. She is hemodynamically stable with no signs of tamponade. Vital signs: BP 115/70, HR 92, RR 18. She is on antiretroviral therapy. What is the appropriate initial management?","options":["A. Emergent pericardiocentesis given the large effusion size","B. Diagnostic pericardiocentesis with fluid analysis, then tailor treatment based on results","C. Initiate anti-tuberculous therapy empirically and defer pericardiocentesis","D. Trial of high-dose NSAIDs and close observation"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient with advanced HIV (CD4 200) and large pericardial effusion requires diagnostic pericardiocentesis to determine the underlying cause (TB, opportunistic infection, malignancy, idiopathic). Fluid analysis (cultures, PCR, ADA, malignant cells, etc.) guides definitive treatment. Since she is hemodynamically stable without tamponade physiology, there is time for diagnostic assessment. Option A: draining without diagnosis misses treatable causes. Option C: TB is high on the differential in advanced HIV with pericardial effusion, but empiric therapy without confirmation risks over-treatment and misses other diagnoses. Option D: NSAIDs alone are inadequate for HIV-related pericarditis with large effusion. Diagnostic pericardiocentesis is the standard approach allowing targeted therapy.","conditionName":"Pericardial Effusion - HIV","system":"CV","subcategory":"Pericardial Disease","tags":["CV","pericardial-effusion","HIV","AIDS","pericardiocentesis"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'diagnostics', 'pending', NOW()),

('q-tax-cv-028', 'clinical-vignette', 'CV', 'hard', '{"question":"A 61-year-old man with diabetes, hypertension, and CKD (eGFR 28) develops acute worsening dyspnea. Chest X-ray shows diffuse bilateral opacities. EKG shows nonspecific ST changes. Troponin is 0.12 ng/mL (elevated). BP is 165/95. Patient is in acute cardiorenal syndrome (worsening renal function with acute HF). Which agent should be AVOIDED?","options":["A. Intravenous furosemide","B. ACE inhibitor (lisinopril)","C. Nitroglycerin infusion","D. Dobutamine infusion"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"In acute cardiorenal syndrome (HF with worsening renal function and hypercreatinemia), ACE inhibitors must be used cautiously or temporarily held because they reduce glomerular filtration pressure via efferent arteriole vasodilation, which can precipitate acute kidney injury. Once the patient is stabilized and fluid status is optimized, ACE-I can be reintroduced. Option A (furosemide): essential for volume overload despite CKD. Option C (nitrates): safe and reduce preload. Option D (dobutamine): can be used cautiously for inotropic support in cardiorenal syndrome. The key insight is that aggressive diuresis + vasodilation (without renal-protective agents) should precede ACE-I reinitiation to prevent AKI exacerbation.","conditionName":"Acute Cardiorenal Syndrome","system":"CV","subcategory":"Heart Failure","tags":["CV","cardiorenal-syndrome","CKD","AKI","acute-HF"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'pharmaceutical', 'pending', NOW()),

('q-tax-cv-029', 'clinical-vignette', 'CV', 'hard', '{"question":"A 75-year-old male with hypertension and mild reduced EF (45%) is noted to have new-onset paroxysmal atrial fibrillation with a CHA2DS2-VASc score of 5. He is currently on lisinopril and hydrochlorothiazide. He has no prior bleeding history. He is now in sinus rhythm but AF recurs. What is the most appropriate anticoagulation and rate control strategy?","options":["A. Warfarin with goal INR 2-3; rate control with diltiazem","B. Aspirin 325 mg daily as anticoagulation; rate control with metoprolol","C. Dabigatran or other DOAC; rate control with beta-blocker","D. No anticoagulation needed if sinus rhythm maintained; observe for recurrence"],"correctAnswer":"C","correctAnswerIndex":0,"explanation":"This patient with new AF and high stroke risk (CHA2DS2-VASc 5) requires anticoagulation regardless of rhythm. DOACs (dabigatran, rivaroxaban, apixaban, edoxaban) are preferred over warfarin in most patients given convenience, no monitoring, and superior efficacy in AF stroke prevention. Rate control with beta-blocker (metoprolol, atenolol) or calcium-channel blocker is appropriate. Option A (warfarin): acceptable but requires INR monitoring and dietary counseling. Option B (aspirin): inadequate for stroke prevention in AF; reserved for CHA2DS2-VASc 0-1. Option D: anticoagulation is indicated by stroke risk score, not rhythm control status.","conditionName":"Atrial Fibrillation - Anticoagulation","system":"CV","subcategory":"Arrhythmias","tags":["CV","AF","anticoagulation","DOAC","stroke-prevention"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'health_maintenance', 'pending', NOW()),

('q-tax-cv-030', 'clinical-vignette', 'CV', 'hard', '{"question":"A 58-year-old male smoker with HTN presents with sudden bilateral lower extremity weakness and back pain. He becomes acutely hypotensive (BP 95/50) with absent lower extremity pulses bilaterally. Emergent CT angiography shows acute aortic dissection extending from the ascending aorta through the descending thoracic aorta and into the abdominal aorta below the renal arteries. Which complication is occurring?","options":["A. Aortic rupture with exsanguination","B. Aortic dissection complicated by acute spinal cord ischemia (spinal artery compromise)","C. Mesenteric ischemia from dissection propagation","D. Acute MI from right coronary artery involvement"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient has aortic dissection complicated by spinal cord ischemia. The bilateral leg weakness with hypotension and back pain, combined with the dissection extending through the descending aorta, indicates compromise of the arteries of Adamkiewicz (usually T9-T12) that supply the anterior spinal cord. This is a catastrophic complication of descending thoracic aortic dissection causing paraplegia. Option A (rupture): likely given hypotension but the imaging shows contained dissection. Option C (mesenteric ischemia): possible but the bilateral leg weakness points to cord ischemia. Option D (MI): less likely given bilateral findings. Spinal cord ischemia in dissection has devastating prognosis; recognition is critical for prognostication and discussion of goals of care.","conditionName":"Aortic Dissection - Spinal Cord Ischemia","system":"CV","subcategory":"Aortic Dissection","tags":["CV","aortic-dissection","spinal-cord-ischemia","paraplegia","complication"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'professional', 'pending', NOW());
